tufteTheme.styles:
body[data-tufte-theme=lenticule-laboratory]{
  color-scheme:light;
  --tufte-bg:#F5F7F4;--tufte-surface:#FFFDF7;--tufte-ink:#172A31;
  --tufte-muted:#3F5C65;--tufte-line:#687F89;--tufte-accent:#3D5588;
  --tufte-warn:#8E650B;--tufte-danger:#983E35;--tufte-radius:0;--tufte-gap:1.25rem;
  --lc-crystal:#00695C;--lc-crystal-soft:#DBEEE8;--lc-plate:#F1F5F1;--lc-grid:rgba(61,85,136,.055);
  color:var(--tufte-ink);background-color:var(--tufte-bg);
  background-image:linear-gradient(var(--lc-grid) 1px,transparent 1px),
    linear-gradient(90deg,var(--lc-grid) 1px,transparent 1px),
    radial-gradient(ellipse at 90% 0%,rgba(0,105,92,.10),transparent 47%);
  background-size:48px 48px,48px 48px,100% 100%;
  font-family:"Roboto Slab","DejaVu Serif",Georgia,serif;font-size:16px;line-height:1.65;
}
body[data-tufte-theme=lenticule-laboratory] :is(button,input,select,textarea){
  font:inherit;background:var(--tufte-surface);border:1px solid var(--tufte-line);border-radius:0;
}
body[data-tufte-theme=lenticule-laboratory] :is(a,button,input,select,textarea):focus-visible{
  outline:3px solid var(--tufte-accent);outline-offset:4px;
}
body[data-tufte-theme=lenticule-laboratory] a{
  color:var(--tufte-accent);text-decoration-thickness:.085em;text-underline-offset:.15em;
}
body[data-tufte-theme=lenticule-laboratory] a:hover{color:var(--lc-crystal)}
body[data-tufte-theme=lenticule-laboratory] .tufte-shell{
  width:min(1250px,100%);padding:clamp(1rem,3.6vw,3.5rem);margin-inline:auto;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-masthead{
  position:relative;isolation:isolate;overflow:hidden;display:grid;
  grid-template-columns:minmax(0,1fr) minmax(14rem,22rem);
  grid-template-areas:"heading lens" "nav nav";align-items:center;
  gap:1rem 1.7rem;min-height:22rem;padding:clamp(1.35rem,4vw,3.25rem);
  margin:0 0 1.2rem;border:1px solid var(--tufte-line);border-top:6px solid var(--tufte-ink);
  border-radius:0;background-color:var(--tufte-surface);
  background-image:linear-gradient(124deg,var(--tufte-surface) 12%,var(--lc-plate) 77%);
  box-shadow:12px 12px 0 rgba(23,42,49,.08);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-masthead::before{
  content:"";grid-area:lens;display:block;width:min(100%,19rem);aspect-ratio:1;
  justify-self:center;align-self:center;
  background:url("/crystal-lens.svg") center/contain no-repeat;opacity:.94;pointer-events:none;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-masthead::after{
  content:"FIG. 01 / RELATIONAL OPTICS";position:absolute;right:1.4rem;top:.7rem;
  font:600 .65rem/1.3 "JetBrains Mono","DejaVu Sans Mono",monospace;
  letter-spacing:.1em;color:var(--tufte-muted);pointer-events:none;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-masthead>div{
  grid-area:heading;min-width:0;max-width:48rem;position:relative;z-index:1;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-eyebrow,
body[data-tufte-theme=lenticule-laboratory] .listing-order,
body[data-tufte-theme=lenticule-laboratory] .tufte-footer{
  font-family:"JetBrains Mono","DejaVu Sans Mono",monospace;font-size:.72rem;
  letter-spacing:.07em;line-height:1.55;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-eyebrow{
  margin-bottom:.75rem;color:var(--lc-crystal);font-weight:750;text-transform:uppercase;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-masthead h1{
  max-width:22ch;margin:0 0 .7rem;color:var(--tufte-ink);
  font-family:"Space Grotesk","DejaVu Sans","Helvetica Neue",Arial,sans-serif;
  font-size:clamp(2.05rem,4.1vw,4rem);font-weight:750;letter-spacing:-.052em;
  line-height:1.07;text-wrap:balance;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-subtitle{
  max-width:62ch;margin:0;color:var(--tufte-muted);font-size:clamp(.96rem,1.2vw,1.1rem);
  line-height:1.65;
}
body[data-tufte-theme=lenticule-laboratory] [data-tufte-navigation]{
  grid-area:nav;display:flex;flex-wrap:wrap;gap:.45rem;padding-top:1rem;
  border-top:1px solid var(--tufte-line);position:relative;z-index:1;
}
body[data-tufte-theme=lenticule-laboratory] [data-tufte-navigation] a{
  display:inline-flex;min-height:2.65rem;align-items:center;padding:.5rem .8rem;
  border:1px solid var(--tufte-line);background:var(--tufte-surface);
  color:var(--tufte-ink);font:650 .76rem/1.3 "Space Grotesk","DejaVu Sans",sans-serif;
  text-decoration:none;letter-spacing:.015em;transition:background-color .14s ease,border-color .14s ease;
}
body[data-tufte-theme=lenticule-laboratory] [data-tufte-navigation] a:hover,
body[data-tufte-theme=lenticule-laboratory] [data-tufte-navigation] [aria-current=page]{
  background:var(--lc-crystal-soft);border-color:var(--lc-crystal);color:var(--tufte-ink);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-grid{gap:1.2rem;align-items:start}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile{
  min-width:0;padding:clamp(1rem,2.2vw,2rem);
  border:1px solid var(--tufte-line);border-radius:0;
  background:var(--tufte-surface);box-shadow:3px 3px 0 rgba(23,42,49,.06);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile[data-role=now]{
  border-top:4px solid var(--lc-crystal);background:var(--tufte-surface);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile[data-role=aside]{
  border-top:4px solid var(--tufte-accent);background:var(--lc-plate);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile>header{
  margin-bottom:1.2rem;padding:0 0 .75rem;border-bottom:1px solid var(--tufte-line);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile h2{
  color:var(--lc-crystal);font:750 .73rem/1.4 "JetBrains Mono","DejaVu Sans Mono",monospace;
  letter-spacing:.12em;text-transform:uppercase;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body{
  color:var(--tufte-ink);font-size:1.03rem;line-height:1.8;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body article{
  max-width:70ch;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body article :is(h1,h2,h3,h4){
  font-family:"Space Grotesk","DejaVu Sans",sans-serif;color:var(--tufte-ink);
  letter-spacing:-.025em;line-height:1.19;text-wrap:balance;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body article h2{
  margin:2.1rem 0 .7rem;padding-top:.85rem;border-top:1px solid var(--tufte-line);
  font-size:clamp(1.35rem,2.2vw,1.85rem);font-weight:750;text-transform:none;letter-spacing:-.025em;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body article h3{
  margin:1.6rem 0 .55rem;font-size:1.2rem;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body article :is(p,ul,ol){max-width:70ch}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body article :is(ol,ul){padding-inline-start:1.55rem}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body article li{padding:.15rem .2rem .35rem}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body article li::marker{color:var(--lc-crystal);font-weight:750}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body blockquote{
  margin:1.6rem 0;padding:.9rem 1.2rem;border-left:4px solid var(--tufte-accent);background:var(--lc-plate);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body :is(pre,code,kbd,samp),
body[data-tufte-theme=lenticule-laboratory] .tufte-table-scroll{
  font-family:"JetBrains Mono","DejaVu Sans Mono",monospace;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body pre{
  max-width:100%;overflow:auto;padding:1.25rem;background:var(--lc-plate);
  border:1px solid var(--tufte-line);border-left:3px solid var(--lc-crystal);
  font-size:.86rem;line-height:1.65;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body :is(figure,table,math){max-width:100%}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body figure{margin:1.5rem 0}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body figcaption{
  color:var(--tufte-muted);font:500 .78rem/1.6 "JetBrains Mono","DejaVu Sans Mono",monospace;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body :is(table,th,td){
  border-color:var(--tufte-line);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body th{
  background:var(--lc-plate);font-family:"Space Grotesk","DejaVu Sans",sans-serif;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-tile-body .listing li{
  padding:.9rem 0;border-bottom:1px solid var(--tufte-line);
}
body[data-tufte-theme=lenticule-laboratory] .tufte-footer{
  margin-top:1.75rem;padding:1rem 0;border-top:2px solid var(--tufte-ink);
  color:var(--tufte-muted);overflow-wrap:anywhere;
}
body[data-tufte-theme=lenticule-laboratory] .tufte-skip{
  background:var(--tufte-surface);border:2px solid var(--tufte-accent);color:var(--tufte-ink);
}
@media(max-width:800px){
  body[data-tufte-theme=lenticule-laboratory] .tufte-shell{padding:1rem}
  body[data-tufte-theme=lenticule-laboratory] .tufte-masthead{
    display:block;min-height:0;padding:1.5rem 1.2rem;margin-bottom:1rem;box-shadow:5px 5px 0 rgba(23,42,49,.07);
  }
  body[data-tufte-theme=lenticule-laboratory] .tufte-masthead::before{
    position:absolute;top:-2rem;right:-3rem;width:13rem;opacity:.18;
  }
  body[data-tufte-theme=lenticule-laboratory] .tufte-masthead::after{right:.7rem;top:.45rem;font-size:.53rem}
  body[data-tufte-theme=lenticule-laboratory] .tufte-masthead>div{position:relative;z-index:1}
  body[data-tufte-theme=lenticule-laboratory] .tufte-masthead h1{font-size:clamp(2rem,7.8vw,3rem)}
  body[data-tufte-theme=lenticule-laboratory] [data-tufte-navigation]{margin-top:1.25rem;gap:.35rem}
  body[data-tufte-theme=lenticule-laboratory] [data-tufte-navigation] a{min-height:2.75rem;padding:.52rem .65rem}
  body[data-tufte-theme=lenticule-laboratory] .tufte-grid{gap:.9rem}
  body[data-tufte-theme=lenticule-laboratory] .tufte-tile{padding:1.25rem}
}
@media(prefers-color-scheme:dark){
  body[data-tufte-theme=lenticule-laboratory]{
    color-scheme:dark;--tufte-bg:#101C22;--tufte-surface:#1A2A30;--tufte-ink:#F1F6F2;
    --tufte-muted:#B7D0CE;--tufte-line:#8CA9AF;--tufte-accent:#C1D3FC;
    --tufte-warn:#E8C277;--tufte-danger:#F5A99C;
    --lc-crystal:#99DED0;--lc-crystal-soft:#284A49;--lc-plate:#20343C;
    --lc-grid:rgba(173,205,210,.05);
  }
  body[data-tufte-theme=lenticule-laboratory] .tufte-masthead{
    background-image:linear-gradient(120deg,var(--tufte-surface),var(--lc-plate));
    border-top-color:var(--lc-crystal);
  }
  body[data-tufte-theme=lenticule-laboratory] .tufte-masthead::before{opacity:.65}
  body[data-tufte-theme=lenticule-laboratory] .tufte-tile{
    box-shadow:3px 3px 0 rgba(0,0,0,.3);
  }
}
@media(prefers-reduced-motion:reduce){
  body[data-tufte-theme=lenticule-laboratory] [data-tufte-navigation] a{transition:none}
}
